(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"vocabulary-comparatives-superlatives":{"title":"Comparatives and Superlatives","topic":"Vocabulary / Word Study","questions":[{"id":"vocabulary-comparatives-superlatives-q0001","version":3,"contentHash":"sha256:e885eebf35813b989111c34963c113bef59eba1118e0851f57e523a999e6f49a","question":"Which sentence uses the comparative form correctly?","choices":["This book is more better than that one.","This book is gooder than that one.","This book is better than that one.","This book is best than that one."],"correct":2,"explanation":{"correct":"Answer: This book is better than that one. The adjective 'good' is irregular, so it changes to the form 'better' when comparing two items, rather than adding -er or 'more'.","incorrect":[{"choice":"This book is more better than that one.","category":"double comparative error","reason":"You should not use 'more' with 'better'. Since 'better' is already a comparative form, adding 'more' creates a redundant phrase."},{"choice":"This book is gooder than that one.","category":"incorrect irregular form","reason":"The word 'good' is an irregular adjective. It does not follow the standard rule of adding '-er'; instead, the correct comparative form is 'better'."},"",{"choice":"This book is best than that one.","category":"superlative vs comparative","reason":"'Best' is the superlative form used to compare three or more items. When comparing only two books, you must use the comparative form 'better' instead."}]},"studyAid":{"definition":"Comparative adjectives compare two items, while superlative adjectives compare three or more. Irregular adjectives change their spelling entirely instead of adding -er or -est.","example":"good/better/best, bad/worse/worst, happy/happier/happiest","strategyClue":"Ask yourself how many things are being compared. If it is only two things, identify if the adjective has a unique irregular form before trying to add suffixes like '-er'.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":1,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0002","version":3,"contentHash":"sha256:c45384eb9c6a5e01ba2d3aff411c232292aa89e976885faa53c59e009fcc42ac","question":"What is the superlative form of 'happy'?","choices":["more happy","happier","happiest","most happier"],"correct":2,"explanation":{"correct":"Answer: happiest. To form the superlative of a two-syllable adjective ending in 'y', you change the 'y' to an 'i' and add '-est'.","incorrect":[{"choice":"more happy","category":"incorrect comparative form","reason":"'More happy' is not the standard superlative form; it describes a comparison between two things rather than identifying the greatest degree."},{"choice":"happier","category":"comparative adjective error","reason":"'Happier' is the comparative form used for comparing two people or things, not for describing the most happy state of all."},"",{"choice":"most happier","category":"double superlative error","reason":"This is a double superlative because it uses both 'most' and the '-er' ending. You should only use one way to show the highest degree."}]},"studyAid":{"definition":"A superlative adjective is used to compare three or more nouns and describes which one has the most of a certain quality.","example":"fast -> fastest, big -> biggest, easy -> easiest","strategyClue":"Check if you are comparing two things or more than two things. If the goal is to show the extreme end of the scale, choose the option that ends in '-est' or uses 'most'.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":2,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0003","version":3,"contentHash":"sha256:2bd78c01808ca7f01d39d5c70a8ba72cce952eef05af5b9188a53654cb54c4f1","question":"Which sentence is correct?","choices":["Of the two dogs, this one is the most fast.","Of the two dogs, this one is the faster.","Of the two dogs, this one is fasterest.","Of the two dogs, this one is more faster."],"correct":1,"explanation":{"correct":"Answer: Of the two dogs, this one is the faster. When comparing exactly two things, use the comparative form of the adjective (faster), not the superlative form.","incorrect":[{"choice":"Of the two dogs, this one is the most fast.","category":"superlative used incorrectly","reason":"The word 'most' is used for comparing three or more things. Since there are only two dogs, you should use the comparative form instead."},"",{"choice":"Of the two dogs, this one is fasterest.","category":"made-up adjective form","reason":"'Fasterest' is not a word in the English language. You cannot combine comparative and superlative endings."},{"choice":"Of the two dogs, this one is more faster.","category":"double comparative error","reason":"You have used both 'more' and the '-er' ending. Since 'faster' is already the comparative form, 'more' is unnecessary and incorrect."}]},"studyAid":{"definition":"Use the comparative form (-er or 'more') to compare two items and the superlative form (-est or 'most') to compare three or more items.","example":"This road is longer (two roads); This is the longest road (three or more roads); She is more careful; She is the most careful.","strategyClue":"Count the number of items being compared in the sentence. If the number is two, look for the choice that uses the '-er' suffix or 'more' by itself.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":3,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0004","version":3,"contentHash":"sha256:06b306510506c76391020d39c82f9a9be6e97c3791372d0734f7531e1398d514","question":"What is the correct comparative form of 'beautiful'?","choices":["beautifuller","more beautiful","most beautiful","beautifuler"],"correct":1,"explanation":{"correct":"Answer: more beautiful. Adjectives with three or more syllables, such as 'beau-ti-ful', do not take '-er' or '-est' endings; instead, we use 'more' to show comparison between two things.","incorrect":[{"choice":"beautifuller","category":"incorrect suffix usage","reason":"Adding '-er' to a long word like 'beautiful' is incorrect. We only add '-er' to short, one-syllable adjectives like 'tall' or 'fast'."},"",{"choice":"most beautiful","category":"superlative vs comparative","reason":"This is a superlative, which is used to compare three or more things. Since the question asks for the comparative form, we use 'more' instead."},{"choice":"beautifuler","category":"incorrect suffix usage","reason":"Similar to 'beautifuller', this adds a suffix to a long adjective. Long words require the addition of 'more' at the beginning, not an ending."}]},"studyAid":{"definition":"To compare two things, use 'more' before long adjectives (three or more syllables) and add '-er' to short adjectives (one or two syllables).","example":"more colorful vs. colorfuler (incorrect); faster vs. more fast (incorrect)","strategyClue":"Clap out the syllables of the word. If the word has three or more claps, decide whether to use 'more' or 'most' instead of changing the word's ending.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":4,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0005","version":3,"contentHash":"sha256:9b3f00fa092c0c0db1715493283c9b51a274948a4edc1efdea41e822f2f96ddc","question":"Which sentence uses the superlative correctly?","choices":["She is the more intelligent student in the class.","She is the most intelligent student in the class.","She is the intelligenter student in the class.","She is the intelligentest student in the class."],"correct":1,"explanation":{"correct":"Answer: She is the most intelligent student in the class. When comparing three or more people, we use the superlative form. For longer adjectives like 'intelligent,' we add 'most' before the word rather than changing its ending.","incorrect":[{"choice":"She is the more intelligent student in the class.","category":"comparative vs superlative","reason":"The word 'more' is used to compare only two people. Since the sentence refers to the whole class, you need the superlative form instead."},"",{"choice":"She is the intelligenter student in the class.","category":"incorrect superlative formation","reason":"Adding '-er' is a way to make a comparative, but 'intelligenter' is not a real word. Longer adjectives use 'more' or 'most' instead of suffixes."},{"choice":"She is the intelligentest student in the class.","category":"incorrect superlative formation","reason":"While '-est' works for short words like 'fastest,' it is not used with longer words like 'intelligent.' Use 'most' instead."}]},"studyAid":{"definition":"Use the comparative (more/-er) to compare two things and the superlative (most/-est) to compare three or more things.","example":"Tall: taller, tallest. Beautiful: more beautiful, most beautiful.","strategyClue":"Count the number of syllables in the adjective. If the word has three or more syllables, look for the 'most' option rather than trying to add an '-est' ending to the word.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":5,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0006","version":3,"contentHash":"sha256:09b6bb96c28ff52370db665edd5e8c222fbeb1bde940d434a4f4c1cee0230a71","question":"What is the comparative form of 'bad'?","choices":["badder","more bad","worse","worst"],"correct":2,"explanation":{"correct":"Answer: worse. 'Bad' is an irregular adjective. Unlike regular adjectives that add '-er', irregular adjectives completely change their form when making comparisons.","incorrect":[{"choice":"badder","category":"incorrect suffix usage","reason":"Adding '-er' to 'bad' is incorrect because 'bad' does not follow the standard rule. We use the irregular form 'worse' instead."},{"choice":"more bad","category":"incorrect modifier usage","reason":"We use 'more' for long adjectives, but 'bad' is an irregular short adjective that changes its entire word structure to 'worse'."},"",{"choice":"worst","category":"superlative vs comparative","reason":"'Worst' is the superlative form, used to compare three or more things. Since a comparison between two things uses the comparative form, 'worse' is the correct choice."}]},"studyAid":{"definition":"Some adjectives are irregular and do not follow the standard rules for forming comparatives or superlatives; they change their spelling entirely.","example":"good/better/best, bad/worse/worst, little/less/least","strategyClue":"Ask yourself if you are comparing only two things. If you are, identify if the adjective is regular or irregular; irregular ones never use 'more' or '-er'.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":6,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0007","version":3,"contentHash":"sha256:54485df972eda4d255ae06fd7f7971de9f06545bb5e1d19a58d0fb329b97f103","question":"Which sentence is written correctly?","choices":["My cat is the most cutest pet in the world.","My cat is the cuter pet in the world.","My cat is the cutest pet in the world.","My cat is the more cutest pet in the world."],"correct":2,"explanation":{"correct":"Answer: My cat is the cutest pet in the world. When comparing three or more things, we use the superlative form of the adjective by adding '-est' to the word.","incorrect":[{"choice":"My cat is the most cutest pet in the world.","category":"double superlative error","reason":"You cannot use 'most' and '-est' together. Since 'cute' becomes 'cutest' by adding the suffix, you do not need the helper word 'most'."},{"choice":"My cat is the cuter pet in the world.","category":"comparative versus superlative","reason":"The word 'cuter' is a comparative form used for two things. Because we are talking about the whole world, use the superlative form 'cutest' instead."},"",{"choice":"My cat is the more cutest pet in the world.","category":"incorrect superlative structure","reason":"Like the double superlative, 'more' is used for comparing two things. Adding 'more' to 'cutest' is incorrect because the '-est' suffix already defines the highest degree."}]},"studyAid":{"definition":"Use the comparative form (ending in -er or with 'more') to compare two things, and the superlative form (ending in -est or with 'most') to compare three or more things.","example":"small -> smaller -> smallest; happy -> happier -> happiest; beautiful -> more beautiful -> most beautiful","strategyClue":"Count the number of things being compared in the sentence. If it is more than two, look for the option that uses the superlative suffix rather than the helper words 'more' or 'most'.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":7,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0008","version":3,"contentHash":"sha256:406a0eb5794ca8a46ceede2dd75450bbaf3ce8bb4ab106806ef78ff478e57040","question":"What is the correct comparative form of 'far' (distance)?","choices":["more far","farer","farther","farthest"],"correct":2,"explanation":{"correct":"Answer: farther. When talking about physical distance, the irregular comparative form of 'far' is 'farther'.","incorrect":[{"choice":"more far","category":"incorrect comparative structure","reason":"We do not add 'more' to the irregular adjective 'far'. Using 'more' with 'far' is not standard English; 'farther' is the correct single-word form."},{"choice":"farer","category":"incorrect suffix usage","reason":"Although many adjectives take an '-er' ending, 'far' is irregular. You cannot add '-er' to this word to create its comparative form."},"",{"choice":"farthest","category":"superlative vs comparative","reason":"'Farthest' is the superlative form, used to compare three or more things. Since you are comparing distance between two points, you need the comparative form, 'farther'."}]},"studyAid":{"definition":"Comparative adjectives compare two items, while superlative adjectives compare three or more. Irregular adjectives, like 'far', do not follow standard '-er' or '-est' spelling rules.","example":"Far/farther/farthest; Good/better/best; Bad/worse/worst.","strategyClue":"Ask yourself if you are comparing two items or three-plus items. Then, remember that some words are 'rule breakers' and change their whole spelling rather than just adding an ending.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":8,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0009","version":3,"contentHash":"sha256:5d036c7114b98147ed8cfc2a2db69437576a06d969b43b192009bcb86a4e8748","question":"Which word correctly completes the sentence? This test was ___ than the last one.","choices":["difficult","more difficult","most difficult","difficultest"],"correct":1,"explanation":{"correct":"Answer: more difficult. We use the comparative form 'more' plus the adjective when comparing exactly two things, such as this test and the last one.","incorrect":[{"choice":"difficult","category":"missing comparative form","reason":"The sentence is comparing two items, so we need a comparative form. Using just 'difficult' does not show that one test is being measured against another."},"",{"choice":"most difficult","category":"superlative vs comparative","reason":"The word 'most' creates a superlative, which is used for comparing three or more things. Since we are only comparing two tests, 'most' is not the correct choice."},{"choice":"difficultest","category":"incorrect suffix usage","reason":"The word 'difficult' is a long adjective, so we use 'more' instead of adding the '-est' suffix. Also, 'difficultest' is not a recognized word in standard English."}]},"studyAid":{"definition":"Use the comparative form of an adjective to compare two people or things. For short adjectives, add '-er'; for longer adjectives, use 'more'.","example":"He is faster than me. This book is more interesting than that one.","strategyClue":"Look at the sentence to see how many things are being compared. If it is exactly two, choose the word that indicates a comparison between two items rather than the extreme of a group.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":9,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0010","version":3,"contentHash":"sha256:a660f1c40171c9de7d538915ec805551892bab96f3aff6ecfc7638c7d602e449","question":"What is the superlative form of 'little' (amount)?","choices":["littler","more little","less","least"],"correct":3,"explanation":{"correct":"Answer: least. When comparing the amount of something among three or more items, we use the superlative form 'least' instead of the comparative form.","incorrect":[{"choice":"littler","category":"incorrect adjective form","reason":"The word 'littler' is an attempt to use a comparative form for size, but it is not the correct superlative form for measuring an amount."},{"choice":"more little","category":"incorrect superlative formation","reason":"Adding 'more' makes an adjective comparative, but 'little' follows an irregular pattern for superlatives, making this phrase grammatically incorrect."},{"choice":"less","category":"comparative instead of superlative","reason":"The word 'less' is a comparative adjective used to compare two things. Since you need the superlative form for comparing more than two items, 'least' is required."},""]},"studyAid":{"definition":"Superlative adjectives are used to describe an object that is at the upper or lower limit of a quality among three or more things.","example":"Little, less, least; Big, bigger, biggest; Good, better, best.","strategyClue":"Ask yourself if the sentence involves comparing two things or three or more. Use the -est or 'most/least' form only when the group being compared contains more than two items.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":10,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0011","version":3,"contentHash":"sha256:4afd734204ba900cb8ebb0b14e5b511e18b31eb7c17d332952d762d6e24a43fb","question":"Which sentence is correct?","choices":["Of all the players, he is the more tall.","Of all the players, he is the most tall.","Of all the players, he is the tallest.","Of all the players, he is the more taller."],"correct":2,"explanation":{"correct":"Answer: Of all the players, he is the tallest. When comparing three or more things, we use the superlative form of the adjective by adding '-est' or using 'most'.","incorrect":[{"choice":"Of all the players, he is the more tall.","category":"incorrect comparative use","reason":"The word 'more' is used when comparing only two people. Since there are 'all the players' (more than two), 'more' is incorrect."},{"choice":"Of all the players, he is the most tall.","category":"incorrect superlative formation","reason":"For short adjectives like 'tall,' we add '-est' to the end instead of using 'most' before the word. 'Tallest' is the correct superlative form."},"",{"choice":"Of all the players, he is the more taller.","category":"double comparative error","reason":"Using 'more' and '-er' together is redundant. Additionally, 'taller' is for comparing two people, not a whole group."}]},"studyAid":{"definition":"Use the comparative form (-er or 'more') to compare two things, and the superlative form (-est or 'most') to compare three or more things.","example":"He is taller than me. (2 people) / He is the tallest on the team. (group)","strategyClue":"First, identify how many items are being compared. If the group size is three or more, look for the word that correctly forms the superlative instead of the comparative.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":11,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0012","version":3,"contentHash":"sha256:2d6b5f6eebfb81e2964674ea14dc266b9e11205672149aacbab5cea5aba3cd5d","question":"What is the comparative form of 'well' (health)?","choices":["weller","more well","better","best"],"correct":2,"explanation":{"correct":"Answer: better. When comparing two people's health, 'well' follows the irregular rule of 'better' instead of adding '-er' or using 'more'.","incorrect":[{"choice":"weller","category":"incorrect suffix rule","reason":"Adding '-er' to 'well' is incorrect because it is an irregular adjective. Some words do not follow the standard rule of adding '-er' to compare two things."},{"choice":"more well","category":"incorrect modifier usage","reason":"We do not use 'more' with 'well'. Because 'well' is irregular, it changes its entire form to 'better' when comparing two people."},"",{"choice":"best","category":"superlative versus comparative","reason":"The word 'best' is the superlative form, used to compare three or more things. When comparing just two things, you must use the comparative form."}]},"studyAid":{"definition":"Comparative adjectives compare two things, while superlative adjectives compare three or more things. Some words, like 'well', are irregular and change their form completely instead of adding '-er' or '-est'.","example":"good/better/best, well/better/best, bad/worse/worst","strategyClue":"Ask yourself if you are comparing two items or more than two. Then, identify if the adjective is one that changes its base word entirely rather than using an ending like '-er'.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":12,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0013","version":3,"contentHash":"sha256:cb7f521c7e03be33c7ab3f5398ff0b27074de62b85f4124e27632ab40a059e23","question":"Which word correctly completes the sentence? This is the ___ book I have ever read.","choices":["more boring","most boring","boringer","boringest"],"correct":1,"explanation":{"correct":"Answer: most boring. When comparing one thing to three or more others, we use the superlative form. Since 'boring' is a multi-syllable word, we use 'most' instead of adding an '-est' suffix.","incorrect":[{"choice":"more boring","category":"comparative adjective error","reason":"This is the comparative form, used when comparing only two things. Because we are comparing this book to all the books ever read, we need the superlative form."},"",{"choice":"boringer","category":"incorrect suffix usage","reason":"'Boringer' is not a real word. Multi-syllable adjectives do not take '-er' or '-est' endings; they use 'more' or 'most' instead."},{"choice":"boringest","category":"incorrect suffix usage","reason":"While '-est' is used for superlatives, it only works for short, one-syllable adjectives. For longer adjectives like 'boring', you must use 'most' to form the superlative."}]},"studyAid":{"definition":"Use 'more' or '-er' for comparing two items. Use 'most' or '-est' for comparing three or more items.","example":"small -> smaller -> smallest; exciting -> more exciting -> most exciting","strategyClue":"Count the syllables in the adjective. If the word has two or more syllables (like 'boring'), avoid adding endings and use 'more' or 'most' instead.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":13,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0014","version":3,"contentHash":"sha256:d68d23af76ff138f32434f908285b8985f2c3a0457d3f47f4b16c2fb63fdbac7","question":"What is the correct form? The blue whale is ___ than an elephant.","choices":["more big","bigger","most big","biggest"],"correct":1,"explanation":{"correct":"Answer: bigger. We use the '-er' suffix to compare two things. Since we are comparing a blue whale to an elephant, 'bigger' is the correct comparative form.","incorrect":[{"choice":"more big","category":"incorrect comparative structure","reason":"For most short, one-syllable adjectives like 'big', we add '-er' to the end rather than adding the word 'more' before the adjective."},"",{"choice":"most big","category":"superlative usage error","reason":"'Most' is used to describe the superlative form (the biggest of all). We use 'more' or '-er' when comparing exactly two things."},{"choice":"biggest","category":"superlative usage error","reason":"The suffix '-est' is used to compare three or more things. When comparing just the whale and the elephant, use the comparative form instead."}]},"studyAid":{"definition":"Comparative adjectives compare two items by adding '-er' to short words or using 'more' with longer words. Superlative adjectives compare three or more items by adding '-est' or using 'most'.","example":"small -> smaller (comparative) / smallest (superlative); fast -> faster (comparative) / fastest (superlative)","strategyClue":"Count the number of items being compared in the sentence. If there are exactly two, look for the form that shows how one is different from the other.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":14,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0015","version":3,"contentHash":"sha256:fbc65c649bfc419991d3184f5cde8ff97c656a013bffb3486a91d3a44532f042","question":"Which sentence uses the comparative correctly?","choices":["This problem is more harder than the first one.","This problem is the hardest than the first one.","This problem is harder than the first one.","This problem is most hard than the first one."],"correct":2,"explanation":{"correct":"Answer: This problem is harder than the first one. For most short adjectives, add '-er' to compare two things. Since 'hard' is a one-syllable word, the correct comparative form is 'harder'.","incorrect":[{"choice":"This problem is more harder than the first one.","category":"double comparative error","reason":"Using 'more' together with '-er' creates a double comparative. You only need the '-er' ending for a short word like 'hard'."},{"choice":"This problem is the hardest than the first one.","category":"superlative used incorrectly","reason":"'Hardest' is a superlative used to compare three or more items. When comparing only two things, stick to the comparative '-er' form."},"",{"choice":"This problem is most hard than the first one.","category":"superlative used incorrectly","reason":"'Most hard' is not a standard comparative phrase. We use the '-er' suffix for short adjectives to make comparisons."}]},"studyAid":{"definition":"Comparatives are used to compare two people, places, or things. For short adjectives, add '-er' to the end of the word.","example":"fast -> faster, tall -> taller, hard -> harder","strategyClue":"Check how many things are being compared. If it is only two, determine if the word is short enough to simply add '-er' instead of using 'more' or 'most'.","link":"https://www.grammar-monster.com/glossary/comparatives.htm","linkText":"Grammar Monster - Comparatives"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["language arts"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":15,"skillIds":[],"standardIds":[]}},{"id":"vocabulary-comparatives-superlatives-q0016","version":3,"contentHash":"sha256:40f053d2ef6a25792e41aa54e83329c4bf4c6a3e1c3f15bd92c0ebd67f5f001d","question":"Which sentence shows a superlative adverb?","choices":["Beth completed the process very efficiently.","Sally works more quickly than most.","Gerald reads quietly in the window seat.","Out of the entire class, Grace works most carefully."],"correct":3,"explanation":{"correct":"Answer: Out of the entire class, Grace works most carefully. The word 'most' turns the adverb 'carefully' into a superlative, which is used to compare an action among three or more people or things.","incorrect":[{"choice":"Beth completed the process very efficiently.","category":"positive degree adverb","reason":"The word 'efficiently' is in the positive degree. It describes an action without comparing it to others."},{"choice":"Sally works more quickly than most.","category":"comparative degree adverb","reason":"The word 'more' makes this a comparative adverb. Use 'more' to compare an action between only two people or things."},{"choice":"Gerald reads quietly in the window seat.","category":"positive degree adverb","reason":"The word 'quietly' is in the positive degree. It simply describes how Gerald reads, without any comparison to other readers."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":16,"sourceFile":"Advanced-1_grammer and usage.pdf","sourceQuestionNumber":8,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Superlative adverbs compare an action among three or more items to show which one has the highest degree of that quality.","example":"Positive: fast; Comparative: faster; Superlative: fastest. Positive: carefully; Comparative: more carefully; Superlative: most carefully.","strategyClue":"Look for the sentence that is comparing one person's action to the entire group rather than just describing the action or comparing two people.","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0017","version":3,"contentHash":"sha256:4d25c4e63e83a41fcb55f4f820ced963f4d4ed466dfee11c976f14960028fec8","question":"Which underlined word is used incorrectly in the sentence? After the first session, several students in the class can sew pajamas better than I.","choices":["After","several","the","I"],"correct":3,"explanation":{"correct":"Answer: I. In this sentence, the word 'I' is used as the object of an implied comparison ('better than I [can sew]'). However, in modern English, 'me' is commonly used as the object of the preposition 'than' in this structure to avoid sounding overly formal or stiff.","incorrect":[{"choice":"After","category":"preposition usage","reason":"'After' is a correctly used preposition here, acting as the start of a prepositional phrase that sets the time for the action."},{"choice":"several","category":"determiner agreement","reason":"'Several' is a correct quantifier used to describe the plural noun 'students'. It is spelled correctly and used appropriately."},{"choice":"the","category":"definite article","reason":"'The' is a correct article used to specify a particular group, 'the class,' so it is functioning exactly as it should."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":17,"sourceFile":"Advanced-2_grammer and usage.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Pronouns change form based on their job in a sentence; use subject pronouns (I, he, she) for actions and object pronouns (me, him, her) after prepositions and comparisons.","example":"Correct: She is taller than me. Incorrect: She is taller than I.","strategyClue":"Try finishing the sentence in your head by adding the missing verb (e.g., '...better than I [can]'). If that sounds too formal for casual speech, replace the subject pronoun with an object pronoun to sound more natural.","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0018","version":3,"contentHash":"sha256:b4a437398ea2bff6ddadf98213367a079184975f4f756b9b9f859b7d2dc3c4cf","question":"Which one of the comparative forms is incorrect?","choices":["good - better- best","well - better - best","nice - nicer - nicest","worse - worser - worsest"],"correct":3,"explanation":{"correct":"Answer: worse - worser - worsest. The comparative form of 'bad' is 'worse' and the superlative is 'worst'. 'Worser' and 'worsest' are not standard English words because the word 'worse' already indicates a comparison.","incorrect":[{"choice":"good - better- best","category":"irregular adjective pattern","reason":"This is actually a correct sequence for the adjective 'good'. The word 'better' compares two things, and 'best' compares three or more."},{"choice":"well - better - best","category":"irregular adverb pattern","reason":"This is a correct sequence for the adverb 'well'. 'Better' and 'best' are the standard comparative and superlative forms used here."},{"choice":"nice - nicer - nicest","category":"regular adjective pattern","reason":"This is a correct sequence. Adjectives that end in a consonant often add -er for comparison and -est for the highest level."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":18,"sourceFile":"Advanced-3_grammer and usage.pdf","sourceQuestionNumber":1,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Comparative adjectives compare two things by adding -er or using 'more', while superlative adjectives compare three or more things by adding -est or using 'most'. Some adjectives, like 'good' and 'bad', are irregular and change their whole spelling.","example":"fast - faster - fastest; big - bigger - biggest; bad - worse - worst","strategyClue":"Check if the base word is irregular. If you can change the word entirely to compare it, do not add '-er' or '-est' to that base word, as that would create a double comparison.","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0019","version":3,"contentHash":"sha256:1304d9adb94c6a5b1facef487704e37bca843e30ccbea924d472669783188d3c","question":"Which is the superlative form of the adjective?","choices":["taller","tallest","very tall","tall"],"correct":1,"explanation":{"correct":"Answer: tallest. The suffix '-est' is added to an adjective to compare three or more items. 'Tallest' describes the one that has the most height in a group.","incorrect":[{"choice":"taller","category":"comparative adjective error","reason":"The suffix '-er' is used to compare only two things. Since this is a superlative, we need a form that shows the highest degree."},"",{"choice":"very tall","category":"intensifier versus superlative","reason":"Adding 'very' makes the adjective stronger, but it does not compare the subject to others in a group like a true superlative form does."},{"choice":"tall","category":"positive degree adjective","reason":"This is the base form of the adjective. It describes one person or object without comparing it to anyone else."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":19,"sourceFile":"Advanced-3_grammer and usage.pdf","sourceQuestionNumber":5,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"A superlative adjective is used to describe an object that is at the highest or lowest limit of a quality among three or more things.","example":"small -> smallest, fast -> fastest, happy -> happiest","strategyClue":"Ask yourself if the sentence is comparing one person or thing to a whole group. If you are describing the 'most' or 'least' of a quality, look for the suffix that denotes the highest degree.","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0020","version":3,"contentHash":"sha256:8cf36214ba1d2f56515dccbabeb421906dae90e82e58b96c3cdf967f05fd6d27","question":"Which set of comparative adjectives is NOT written correctly?","choices":["h appy - happier - happiest","friendly - friendlier - f riendliest","silly - sillyer - sillyest","funny - funnier - funniest"],"correct":2,"explanation":{"correct":"Answer: silly - sillyer - sillyest. Adjectives ending in 'y' that have two syllables follow a specific rule: drop the 'y' and add '-ier' for the comparative and '-iest' for the superlative.","incorrect":[{"choice":"h appy - happier - happiest","category":"correct comparative form","reason":"This is actually a correct example of the rule! You correctly changed the 'y' to an 'i' before adding '-er' and '-est'."},{"choice":"friendly - friendlier - f riendliest","reason":"\"friendly - friendlier - f riendliest\" fits the word pattern or category, so it is not the odd one out."},"",{"choice":"funny - funnier - funniest","category":"correct comparative form","reason":"This choice is written correctly because the 'y' was changed to an 'i' to form the comparative and superlative degrees."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":20,"sourceFile":"Advanced-6_grammer and usage.pdf","sourceQuestionNumber":5,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"When an adjective ends in 'y', you must drop the 'y' and replace it with an 'i' before adding the endings '-er' or '-est'.","example":"sunny -> sunnier -> sunniest; messy -> messier -> messiest","strategyClue":"Look closely at the letter before the suffix in each set. If you see the original 'y' still standing right next to the '-ier' or '-iest', that form has broken the spelling rule.","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0021","version":3,"contentHash":"sha256:35e8c14df1fedaa29ef7debfe5636fb7d35260ef61c15f2883dfcf60773ffad5","question":"Which sentence contains the correct comparison?","choices":["Belind a is the olde st of the two sisters.","Belinda is the older of the two sisters.","Belinda is the most oldof the two sisters.","Belinda is the more oldof the two sisters."],"correct":1,"explanation":{"correct":"Answer: Belinda is the older of the two sisters. When comparing exactly two people, we use the comparative adjective form ending in '-er' rather than the superlative form.","incorrect":[{"choice":"Belind a is the olde st of the two sisters.","category":"spelling error","reason":"This choice contains typos where the words 'Belinda' and 'oldest' have been split into two separate words. Always ensure your adjectives are spelled correctly."},"",{"choice":"Belinda is the most oldof the two sisters.","category":"superlative vs comparative","reason":"We use 'most' for superlatives when comparing three or more things. Since there are only two sisters, 'most' is incorrect here."},{"choice":"Belinda is the more oldof the two sisters.","category":"incorrect comparative structure","reason":"The word 'old' is a one-syllable adjective, so we form the comparative by adding '-er' to the end. 'More old' is not the standard way to compare single-syllable adjectives."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":21,"sourceFile":"Basic-1_grammer and usage.pdf","sourceQuestionNumber":2,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Use the '-er' form (comparative) to compare two things, and the '-est' form (superlative) to compare three or more things.","example":"He is taller than his brother. She is the tallest girl in the entire class.","strategyClue":"Count the number of items being compared in the sentence. If there are exactly two, look for the adjective ending in '-er'.","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0022","version":4,"contentHash":"sha256:c882e48f017535d5e11223a02265e55f5af5f0eab8711bdcc33b05a74c07a4f8","question":"Choose the best missing word. Yesterday was the _______ day of the year.","choices":["cold er","cold","coldest","coldess"],"correct":2,"explanation":{"correct":"Answer: coldest. When comparing one thing to three or more things in a group (like all the days in a year), we use the superlative form ending in '-est'.","incorrect":[{"choice":"cold er","category":"comparative adjective error","reason":"The suffix '-er' is used to compare only two things. Since there are many days in a year, we need the superlative form, not the comparative one."},{"choice":"cold","category":"positive degree adjective","reason":"The plain form 'cold' describes one day, but it does not show that this day stands out from all the others in the year."},"",{"choice":"coldess","category":"spelling and suffix error","reason":"'Coldess' is not a correctly spelled word. The superlative form of 'cold' is 'coldest', which adds the '-est' suffix to the end of the base word."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":22,"sourceFile":"Basic-2_grammer and usage.pdf","sourceQuestionNumber":2,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Use '-er' when comparing two items and '-est' when comparing three or more items in a group.","example":"small -> smaller -> smallest; fast -> faster -> fastest","strategyClue":"Look for words like 'the' before the blank and identify if the sentence is talking about one item in a large group or comparing two specific things.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"vocabulary-comparatives-superlatives-q0023","version":4,"contentHash":"sha256:1fdc99378f055c13bb79045f1aa5cd7b9f0d2cbaa77468957acb39af4955dbfa","question":"Choose the best missing word. Many people think peanut butter is _______ than jelly.","choices":["good","better","gooder","best"],"correct":1,"explanation":{"correct":"Answer: better. When comparing two things—in this case, peanut butter and jelly—use the comparative form of the adjective, which is 'better'.","incorrect":[{"choice":"good","category":"positive degree adjective","reason":"The word 'good' is the base form and is used for describing a single noun. Since we are comparing two items using 'than', we need the comparative form instead."},"",{"choice":"gooder","category":"incorrect irregular comparison","reason":"'Gooder' is not a word in standard English. 'Good' is an irregular adjective, meaning its comparative form changes completely to 'better' rather than adding '-er'."},{"choice":"best","category":"superlative degree error","reason":"'Best' is the superlative form, used when comparing three or more things. Because the sentence only compares two items, 'better' is the correct choice."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":23,"sourceFile":"Basic-5_grammer and usage.pdf","sourceQuestionNumber":1,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Use the comparative form of an adjective to compare two things and the superlative form to compare three or more things.","example":"small / smaller / smallest; good / better / best; happy / happier / happiest","strategyClue":"Check how many things are being compared in the sentence. If there are exactly two items linked by the word 'than', always look for the comparative form.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"vocabulary-comparatives-superlatives-q0024","version":3,"contentHash":"sha256:d7eb1f663e372ea73a0919d0b84ecd545f4a0864f84f7e6cf5b2225a2b088f2b","question":"Choose the correct wordor words to complete this sentence? Elvis was the __________ singer of all time.","choices":["great","greater","greatest","more greater"],"correct":2,"explanation":{"correct":"Answer: greatest. We use the superlative form 'greatest' to compare one person (Elvis) to all others in the entire group of singers.","incorrect":[{"choice":"great","category":"positive degree adjective","reason":"The word 'great' is just a description. It doesn't compare Elvis to anyone else, so it doesn't fit the phrase 'of all time'."},{"choice":"greater","category":"comparative degree adjective","reason":"We use 'greater' to compare only two people or things. Since Elvis is being compared to 'all' singers, we need the superlative form instead."},"",{"choice":"more greater","category":"double comparative error","reason":"Adding 'more' before 'greater' is incorrect because 'greater' is already a comparative word. Never use two comparative words at the same time."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":24,"sourceFile":"Basic-6_grammer and usage.pdf","sourceQuestionNumber":2,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Superlative adjectives describe one thing in a group that has the most or least of a certain quality, usually by adding '-est' or using 'most'.","example":"fast -> fastest, happy -> happiest, talented -> most talented","strategyClue":"Look at the phrase 'of all time' at the end of the sentence. This signals that you are comparing one person to a very large group, not just two items.","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0025","version":3,"contentHash":"sha256:13ad07d72a66c5b7ff3173fb9712bea13508658cf1b7313b1ae77092295c4123","question":"Choose the correct word to complete this sentence. The right answer is usually the _________ choice.","choices":["worst","b est","least","most"],"correct":1,"explanation":{"correct":"Answer: best. This sentence uses the word 'usually' to suggest the highest-quality or most favorable option, making 'best' the correct superlative adjective to describe the right answer.","incorrect":[{"choice":"worst","category":"opposite meaning","reason":"The word 'worst' means the lowest quality, which contradicts the idea of finding the 'right' or correct answer."},"",{"choice":"least","category":"incorrect superlative","reason":"The word 'least' suggests the smallest amount of something, which does not logically describe the quality of a 'right' answer."},{"choice":"most","category":"incomplete phrase","reason":"While 'most' can be a superlative, it is usually followed by another adjective (like 'most helpful'). By itself, it doesn't clearly describe the quality of the answer choice."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":25,"sourceFile":"Basic-7_grammer and usage.pdf","sourceQuestionNumber":1,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Superlative adjectives compare three or more things and show which one has the most or least of a quality.","example":"good/best, bad/worst, tall/tallest, happy/happiest.","strategyClue":"Think about the context of the sentence: does it describe something that is highly favorable and correct, or something negative and incorrect?","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0026","version":4,"contentHash":"sha256:8b33822038bd14c2c7cc14a1d5858ab047cd4b904816ce40620e2f4d71f830b2","question":"Choose the missing word. Yesterday, I had the _______ dinner ever.","choices":["b addest","worst","worstest","worse"],"correct":1,"explanation":{"correct":"Answer: worst. 'Worst' is the superlative form of 'bad,' used when comparing something to all others in a group. Since the sentence refers to the absolute extreme of the dinner, we use the superlative form.","incorrect":[{"choice":"b addest","category":"non-standard spelling","reason":"This is not a real word. The superlative form of 'bad' is an irregular form, meaning it does not follow the standard rule of adding '-est'."},"",{"choice":"worstest","category":"double superlative","reason":"You should not add '-est' to 'worst' because 'worst' is already the superlative form. It is already at the extreme limit."},{"choice":"worse","category":"comparative adjective error","reason":"'Worse' is the comparative form used when comparing only two things. Because we are talking about the dinner compared to *all* others, we need the superlative form."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":26,"sourceFile":"Proficient-1_grammer and usage.pdf","sourceQuestionNumber":1,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Use the comparative form (-er or 'more') to compare two things, and the superlative form (-est or 'most') to compare three or more things.","example":"Bad (good), worse (better), worst (best). Example: 'This is the worst movie I have ever seen.'","strategyClue":"Ask yourself if you are comparing two specific items or describing one item as the extreme of the whole group. If you are describing the extreme of the whole group, choose the superlative form.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"vocabulary-comparatives-superlatives-q0027","version":4,"contentHash":"sha256:03cb49b0f9481b1a98422afeeaccdeb7b95b6e4d806d54fc8885d465f0db179f","question":"Choose the best missing wordor words. My broken leg was the ______ injury I have ever had.","choices":["p ainfullest","more painful","most painful","more painfullest"],"correct":2,"explanation":{"correct":"Answer: most painful. When comparing one thing to three or more others (or the entire group of injuries you have had), you must use the superlative form 'most' followed by the adjective.","incorrect":[{"choice":"p ainfullest","category":"nonexistent word form","reason":"The word 'painfullest' is not a real word. Also, for longer adjectives like 'painful,' we add 'most' before the word instead of adding '-est' to the end."},{"choice":"more painful","category":"comparative adjective error","reason":"'More painful' is used when comparing exactly two things. Since you are comparing this injury to every other injury you have ever had (a group of many), you need the superlative form."},"",{"choice":"more painfullest","category":"double superlative error","reason":"This choice incorrectly mixes two different ways to make a comparison. You should only use either 'most' or the '-est' suffix, never both together, and 'painfullest' is not a standard word."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":27,"sourceFile":"Proficient-2_grammer and usage.pdf","sourceQuestionNumber":1,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Use the comparative (more/-er) to compare two things and the superlative (most/-est) to compare three or more things.","example":"This book is funnier than that one. This book is the funniest one in the library.","strategyClue":"Ask yourself if the sentence is comparing the injury to only one other thing or to all past injuries. If it refers to a whole group, look for the word that expresses the highest degree.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"vocabulary-comparatives-superlatives-q0028","version":4,"contentHash":"sha256:dc02f12784830f83851b459dab2ecee8a612d61da11311bb8f8e15fe87e42344","question":"Choose the best missing wordor words. Joey was the _____ childon the block when he got a new bike for his birthday.","choices":["mo re happy","most happiest","happier","happiest"],"correct":3,"explanation":{"correct":"Answer: happiest. The sentence compares Joey to all other children on the block, so you must use the superlative form of the adjective 'happy' by adding '-est'.","incorrect":[{"choice":"mo re happy","category":"incorrect comparative form","reason":"This phrase is written with an extra space and uses the wrong degree. 'More happy' is used for comparing only two things, and it is spelled incorrectly here."},{"choice":"most happiest","category":"double superlative","reason":"You should not use 'most' and '-est' together. 'Happiest' already means the most happy, so adding 'most' is unnecessary and incorrect."},{"choice":"happier","category":"comparative degree","reason":"Use 'happier' only when comparing Joey to one other person. Since the sentence talks about all the children on the block, you need the superlative form."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":28,"sourceFile":"Proficient-3_grammer and usage.pdf","sourceQuestionNumber":1,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Use the comparative (-er) to compare two things and the superlative (-est) to compare three or more things.","example":"Tall, taller, tallest; Small, smaller, smallest.","strategyClue":"Ask yourself how many people are being compared. If it is more than two, choose the form that ends in '-est'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"vocabulary-comparatives-superlatives-q0029","version":4,"contentHash":"sha256:e254aa430471325ba743b852521fde0a267549d26da0e655ca0a7a66b524a4ef","question":"Choose the best missing wordor words. She was _______ after the race than before.","choices":["t ired","more tired","more tireder","most tiredest"],"correct":1,"explanation":{"correct":"Answer: more tired. When comparing two things—in this case, her tiredness level at two different times—we use the comparative form 'more' with the adjective 'tired'.","incorrect":[{"choice":"t ired","category":"missing comparative word","reason":"This is just the base adjective. Because the sentence uses 'than' to compare two moments in time, you must add the word 'more' to show the difference."},"",{"choice":"more tireder","category":"double comparative error","reason":"You should not use 'more' and '-er' together. 'Tireder' is not the correct way to form the comparative of 'tired', so we use 'more tired' instead."},{"choice":"most tiredest","category":"superlative usage error","reason":"The 'most' and '-est' forms are for comparing three or more things. Since we are only comparing two points in time ('after the race' vs. 'before'), use the comparative form instead."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":29,"sourceFile":"Proficient-3_grammer and usage.pdf","sourceQuestionNumber":3,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Use the comparative form (more + adjective or adjective + -er) to compare two things, and the superlative form (most + adjective or adjective + -est) to compare three or more things.","example":"He is faster than me. She is the fastest runner. The cake was more delicious than the pie. This is the most delicious cake.","strategyClue":"Look at the sentence to see how many items or times are being compared. If you see the word 'than', ask yourself if you are comparing exactly two things to decide between comparative or superlative forms.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"vocabulary-comparatives-superlatives-q0030","version":3,"contentHash":"sha256:55d3101cb936d3e80353b3bbe85758202c7b28f81c1b4157eb6b0ab8d665bc12","question":"Which group of letters are adjectives? Several older homes stood along the pleas ant tree-lined block. A B C D E F","choices":["A, C, D","B, D, E","B, E, F","A, E"],"correct":3,"explanation":{"correct":"Answer: A, E. The words 'older' and 'pleasant' are adjectives because they describe the nouns 'homes' and 'block'. Adjectives provide more detail about people, places, or things.","incorrect":[{"choice":"A, C, D","category":"incorrect word identification","reason":"While 'older' is an adjective, 'along' is a preposition and 'tree-lined' is a compound adjective. 'A, C, D' includes words that do not describe the nouns in the sentence."},{"choice":"B, D, E","category":"incorrect word identification","reason":"'Several' and 'tree-lined' act as adjectives, but 'stood' is an action verb. 'B, D, E' includes a word that shows action rather than describing a noun."},{"choice":"B, E, F","category":"incorrect word identification","reason":"'Several' is a quantifier, but 'along' is a preposition and 'block' is a noun. These words do not all function as adjectives in the sentence."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["vocabulary","word study","usage"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":30,"sourceFile":"Proficient-7_grammer and usage.pdf","sourceQuestionNumber":8,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"An adjective is a word that describes or modifies a noun or pronoun by telling us which one, what kind, or how many.","example":"The tall (adjective) man walked. I have three (adjective) red (adjective) balloons.","strategyClue":"Look at each word in the group and ask yourself: 'Does this word tell me what kind, which one, or how many about the nouns in the sentence?' If it describes the noun, it is an adjective.","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0031","version":3,"contentHash":"sha256:12b1fab7fee45e835836d9b6b3f7fa43eb4289f5c223ffaa3b72d01fb5e2fb2c","question":"Which words best complete this sentence? Greg is ____________ his father, George.","choices":["tallest than","taller than","taller from","tall than"],"correct":1,"explanation":{"correct":"Answer: taller than. When comparing two people, we use the comparative form of the adjective ending in '-er' followed by the word 'than'.","incorrect":[{"choice":"tallest than","category":"superlative vs comparative","reason":"The '-est' suffix is used for comparing three or more things. Since we are only comparing Greg and his father, we must use the comparative form 'taller'."},"",{"choice":"taller from","category":"incorrect preposition","reason":"The word 'than' is the required conjunction to complete a comparison. 'From' does not work in this specific grammatical structure."},{"choice":"tall than","category":"missing comparative suffix","reason":"Because you are comparing two people, you need the comparative form of the adjective, which adds '-er' to the base word 'tall'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["vocabulary","word study","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":31,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":36,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"To compare two people or things, add '-er' to the adjective and use the word 'than'.","example":"He is shorter than me. She is faster than her brother.","strategyClue":"Count the number of people being compared in the sentence. If you see two names or items, look for the option that expresses a direct comparison between that pair.","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0032","version":4,"contentHash":"sha256:4181c3bbb8f32307d104b8124e894759f5a418e4a912a60a333af14a22ada171","question":"Choose the correct wordor words to complete the sentence below. This one is _________ than thatone.","choices":["good","better","more good","be st"],"correct":1,"explanation":{"correct":"Answer: better. When comparing two things, you must use the comparative form of an adjective. The comparative form of 'good' is the irregular word 'better'.","incorrect":[{"choice":"good","category":"positive degree adjective","reason":"The word 'good' is the base form of the adjective and is used to describe one thing. When you see the word 'than' comparing two items, you need the comparative form instead."},"",{"choice":"more good","category":"double comparative error","reason":"English does not use 'more' with irregular comparative adjectives like 'better'. You simply use 'better' to show the higher degree of quality."},{"choice":"be st","category":"superlative degree error","reason":"The word 'best' is a superlative used to compare three or more things. Since the sentence compares only two things ('this one' and 'that one'), you should use the comparative form."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["vocabulary","word study","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":32,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":37,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"Comparative adjectives compare two items or people, while superlative adjectives compare three or more. Most short words add '-er' for comparison, but some change their entire spelling.","example":"small -> smaller -> smallest; good -> better -> best; bad -> worse -> worst","strategyClue":"Look for the word 'than' in the sentence. When you see 'than' comparing two distinct items, remember that you need a word that shows comparison rather than the base word or the superlative.","link":"","linkText":""}},{"id":"vocabulary-comparatives-superlatives-q0033","version":3,"contentHash":"sha256:92571ba9c77070dee04b149f12d277816eface390e7de6ca9cb6303bb393b7d0","question":"Which setof words will complete the sentence below? The lettuce was ________ than the carrots, but the tomatoes were ______ ___ of all.","choices":["f resher, freshest","fresher, most freshest","more fresher, freshest","more fresher, most freshest"],"correct":0,"explanation":{"correct":"Answer: fresher, freshest. When comparing two things, add '-er' to the adjective (fresher). When comparing three or more things, use the '-est' form (freshest).","incorrect":["",{"choice":"fresher, most freshest","category":"double superlative","reason":"You should not use 'most' with an adjective that already ends in '-est'. The word 'freshest' already expresses the superlative, so adding 'most' is redundant."},{"choice":"more fresher, freshest","category":"double comparative","reason":"You should not use 'more' with an adjective that already ends in '-er'. 'Fresher' is already the comparative form, so 'more' is unnecessary."},{"choice":"more fresher, most freshest","category":"double comparative and superlative","reason":"This choice uses both double comparatives and double superlatives. Always use either the '-er/-est' ending or 'more/most', but never both at the same time."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["vocabulary","word study","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"vocabulary-comparatives-superlatives","sequence":33,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":1,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["vocabulary.word-study"],"standardIds":["L.3-6.5","L.4-6.4"]},"studyAid":{"definition":"To compare two things, add '-er' to the adjective. To compare three or more things, add '-est' to the adjective.","example":"small -> smaller -> smallest; fast -> faster -> fastest; cold -> colder -> coldest","strategyClue":"Count the items being compared. If comparing two things, look for the word ending in '-er'. If comparing the whole group, look for the word ending in '-est', and avoid words like 'more' or 'most' with those forms.","link":"","linkText":""}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
